// Top parcels table: the highest-ranked parcels in Hennepin County, a city, or a watershed district.
//
// Ask (Bryan, 2026-11-12): "create a table option to see the top parcels for the county and then
// by each jurisdiction layer provided in the clip and zip. On select in the table, it should select
// the parcel on the map and provide a 'zoom to' option"; "it should play nice with the 'zoom to'
// tool as well".
//
// Data: data/top-parcels.json, generated by 06-output-20261112-make-protected-data.py (task dir
// 2026-W46 THU 01) and fetched the first time the table opens (nothing extra at page load). Ranks
// are the re-rank without already-protected and MSP Airport parcels (js/protected-v1.js). A parcel
// belongs to the city / watershed district holding its centroid. Up to top_n rows per area.
//
// One state with the Zoom to tool: the tool's checkboxes are the area selection.
// - Zoom to -> table: ticking areas (or Clear) re-scopes the table; no map movement.
// - Table -> Zoom to: picking an area in the table ticks it in Zoom to (its outline, Clip & Zip
//   extent and, on branch city-mask, its grey mask) and frames it with the Zoom button's own code.
//   Picking Hennepin County clears the Zoom to selection and does not move the map.
// - A row selects the parcel through the map's popup (the same selection a map click makes); its
//   Zoom to button uses window.NRPCZoomTo.zoomToExtent, the Zoom to tool's own zoom.
// - One parcel highlight at a time: the popup's. The selected row follows the popup (a map click
//   on a listed parcel marks its row; closing the popup clears it); a scope change that drops the
//   selected parcel closes the popup.

window.NRPCTopParcels = (() => {
  const PAGE = 50;
  const MIN_PARCEL_EXTENT_M = 500;   // a tiny lot is framed in at least 500 m of context
  const fmt = n => n.toLocaleString("en-US");
  let view, model, data = null, loading = null;
  let scope = { kind: "county" };    // {kind: county} | {kind: city|watershed, names: [..]}
  let shown = PAGE, rows = [], selectedPid = null, driving = false;
  let panel, btn, kindSel, areaSel, scopeNote, tbody, moreBtn, countLine, statusLine;

  // ── Zoom to tool (its own DOM: #city-checkbox-scroll, #city-zoom-btn, #city-clear-btn) ──────
  const zt = {
    scroll: () => document.getElementById("city-checkbox-scroll"),
    checked() {
      const s = this.scroll();
      if (!s) return { kind: "county" };
      if (s.querySelector("#city-cb-full-county:checked")) return { kind: "county", full: true };
      const boxes = [...s.querySelectorAll("input[data-type]:checked")];
      if (!boxes.length) return { kind: "county" };
      const kinds = [...new Set(boxes.map(b => b.dataset.type))];
      return { kind: kinds.length === 1 ? kinds[0] : "mixed",
               items: boxes.map(b => ({ kind: b.dataset.type, name: b.value })) };
    },
    box(kind, name) {
      return [...(this.scroll() || document).querySelectorAll(`input[data-type='${kind}']`)]
        .find(b => b.value === name);
    },
    select(kind, name) {               // tick one area, the way a click in the list would
      driving = true;
      try {
        document.getElementById("city-clear-btn")?.click();
        if (kind === "county") return true;
        const b = this.box(kind, name);
        if (!b) return false;
        b.checked = true;
        b.dispatchEvent(new Event("change", { bubbles: true }));
        document.getElementById("city-zoom-btn")?.click();   // the tool's own framing
        return true;
      } finally { driving = false; }
    },
  };

  function scopeFromZoomTo() {
    const c = zt.checked();
    if (c.kind === "county") return { kind: "county" };
    return { kind: c.kind, items: c.items };
  }

  // ── rows for a scope ────────────────────────────────────────────────────────────────────
  function rowsFor(s) {
    const S = data.scopes;
    if (s.kind === "county") return S.county.map(i => data.rows[i]);
    const seen = new Set(), out = [];
    s.items.forEach(it => (S[it.kind][it.name] || []).forEach(i => {
      if (!seen.has(i)) { seen.add(i); out.push(data.rows[i]); }
    }));
    return out.sort((a, b) => a[1] - b[1] || (a[0] < b[0] ? -1 : 1));
  }

  function scopeLabel(s) {
    if (s.kind === "county") return "Hennepin County";
    const nm = it => it.kind === "watershed" ? titleCase(it.name) : it.name;
    return s.items.length === 1 ? nm(s.items[0]) : `${s.items.length} areas: ${s.items.map(nm).join(", ")}`;
  }
  const titleCase = str => str.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());

  // ── render ──────────────────────────────────────────────────────────────────────────────
  function syncPickers() {
    const single = scope.kind !== "county" && scope.items.length === 1 ? scope.items[0] : null;
    if (scope.kind === "county") kindSel.value = "county";
    else if (single) kindSel.value = single.kind;
    else kindSel.value = "zoomto";
    kindSel.querySelector("option[value=zoomto]").hidden = !(scope.kind !== "county" && !single);
    fillAreas(kindSel.value, single ? single.name : null);
  }

  function fillAreas(kind, selectedName) {
    areaSel.innerHTML = "";
    const list = kind === "city" ? data.cities : kind === "watershed" ? data.watersheds : [];
    areaSel.disabled = !list.length;
    areaSel.hidden = !list.length;
    if (!list.length) return;
    const ph = document.createElement("option");
    ph.value = ""; ph.textContent = kind === "city" ? "Choose a city..." : "Choose a district...";
    areaSel.appendChild(ph);
    list.forEach(n => {
      const o = document.createElement("option");
      o.value = n; o.textContent = kind === "watershed" ? titleCase(n) : n;
      areaSel.appendChild(o);
    });
    areaSel.value = selectedName || "";
  }

  function render() {
    rows = rowsFor(scope);
    const D = window.NRPCProtectedV1;
    scopeNote.textContent = `Top parcels in ${scopeLabel(scope)}` +
      (scope.kind !== "county" && zt.checked().kind !== "county" ? " (from Zoom to)" : "");
    statusLine.textContent = `Ranked over ${fmt(data.parcels_ranked)} parcels. Already-protected ` +
      `(${fmt(data.excluded.protected)}) and MSP Airport (${fmt(data.excluded.msp)}) parcels are ` +
      `not ranked and not listed. Area = the city or district holding the parcel's centroid.`;
    tbody.innerHTML = "";
    const n = Math.min(shown, rows.length);
    rows.slice(0, n).forEach((r, i) => tbody.appendChild(rowEl(r, i + 1)));
    countLine.textContent = `Showing ${fmt(n)} of ${fmt(rows.length)}` +
      (rows.length >= data.top_n && scope.kind !== "mixed" && (scope.items || []).length <= 1
        ? ` (top ${fmt(data.top_n)} per area in this build)` : "");
    moreBtn.hidden = n >= rows.length;
    markSelected();
  }

  function rowEl(r, pos) {
    const [pid, rank, cls, acres, ov, city, ws, addr] = r;
    const tr = document.createElement("tr");
    tr.tabIndex = 0;
    tr.dataset.pid = pid;
    tr.setAttribute("aria-selected", "false");
    const c = window.NRPCModelV1.CLASSES[cls];
    const cells = [
      fmt(pos), fmt(rank),
      `<span class="tp-swatch" style="background:${c.color}"></span>${data.class_labels[cls]}`,
      pid, addr || "", data.cities[city] || "", acres.toFixed(2), ov.toFixed(4),
    ];
    cells.forEach((v, k) => {
      const td = document.createElement("td");
      if (k === 2) td.innerHTML = v; else td.textContent = v;
      if (k === 0 || k === 1 || k >= 6) td.className = "tp-num";
      tr.appendChild(td);
    });
    const td = document.createElement("td");
    const z = document.createElement("button");
    z.type = "button"; z.className = "tp-zoom"; z.textContent = "Zoom to";
    z.setAttribute("aria-label", `Zoom to parcel ${pid}`);
    z.addEventListener("click", e => { e.stopPropagation(); selectParcel(pid, true); });
    td.appendChild(z);
    tr.appendChild(td);
    tr.addEventListener("click", () => selectParcel(pid, false));
    tr.addEventListener("keydown", e => {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); selectParcel(pid, false); }
      if (e.key === "ArrowDown") { e.preventDefault(); tr.nextElementSibling?.focus(); }
      if (e.key === "ArrowUp") { e.preventDefault(); tr.previousElementSibling?.focus(); }
    });
    return tr;
  }

  function markSelected() {
    tbody.querySelectorAll("tr").forEach(tr => {
      const on = tr.dataset.pid === selectedPid;
      tr.classList.toggle("tp-selected", on);
      tr.setAttribute("aria-selected", on ? "true" : "false");
    });
  }

  // ── select / zoom through the map's own popup and the Zoom to tool's zoom ───────────────
  function turnModelOn() {
    let l = model.layer;
    while (l && l !== view.map) { if (l.visible === false) l.visible = true; l = l.parent; }
  }

  async function selectParcel(pid, zoom) {
    turnModelOn();
    const q = model.layer.createQuery();
    q.where = `PID = '${pid.replace(/'/g, "''")}'`;
    q.outFields = ["*"];
    q.returnGeometry = true;
    q.outSpatialReference = view.spatialReference;
    const res = await model.layer.queryFeatures(q);
    const f = res.features[0];
    if (!f) { statusLine.textContent = `Parcel ${pid} not found in the model layer.`; return; }
    selectedPid = pid;
    markSelected();
    if (zoom) {
      let e = f.geometry.extent.clone();
      const grow = MIN_PARCEL_EXTENT_M / Math.max(e.width, e.height, 1);
      if (grow > 1) e = e.expand(grow);
      await window.NRPCZoomTo.zoomToExtent(e, window.NRPCZoomTo.AREA_FACTOR);
    }
    const at = f.geometry.centroid || f.geometry.extent.center;
    view.openPopup({ features: [f], location: at });
  }

  function onPopupChange() {
    const g = view.popup && view.popup.visible ? view.popup.selectedFeature : null;
    const pid = g && g.layer === model.layer ? g.attributes.PID : null;
    if (pid !== selectedPid) { selectedPid = pid; if (tbody) markSelected(); }
  }

  // drop a selection that the new scope no longer lists
  function dropStaleSelection() {
    if (selectedPid && !rows.some(r => r[0] === selectedPid)) {
      selectedPid = null;
      view.closePopup ? view.closePopup() : (view.popup.visible = false);
    }
  }

  function setScope(s) {
    scope = s; shown = PAGE;
    if (!data) return;
    syncPickers(); render(); dropStaleSelection();
  }

  // ── CSV of the rows shown ────────────────────────────────────────────────────────────────
  function csv() {
    const head = ["rank_in_scope", "rank_ranked_parcels", "class", "PID", "address", "city",
                  "watershed_district", "acres", "overall_value", "published_rank"];
    const q = v => /[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v);
    const lines = [head.join(",")];
    rows.slice(0, Math.min(shown, rows.length)).forEach((r, i) => {
      lines.push([i + 1, r[1], data.class_labels[r[2]], r[0], r[7], data.cities[r[5]] || "",
                  data.watersheds[r[6]] || "", r[3], r[4], r[8]].map(q).join(","));
    });
    const blob = new Blob([lines.join("\n") + "\n"], { type: "text/csv" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `top-parcels-${scopeLabel(scope).replace(/[^A-Za-z0-9]+/g, "-").toLowerCase()}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  }

  // ── panel ────────────────────────────────────────────────────────────────────────────────
  function buildPanel() {
    panel = document.createElement("section");
    panel.id = "top-parcels-panel";
    panel.className = "hidden";
    panel.setAttribute("aria-label", "Top parcels");
    panel.innerHTML = `
      <div class="tp-head">
        <button type="button" class="tp-grip" aria-label="Collapse or expand the table"></button>
        <h2 class="tp-title">Top parcels</h2>
        <button type="button" class="tp-close" aria-label="Close Top parcels">&times;</button>
      </div>
      <div class="tp-body">
        <div class="tp-pickers">
          <label class="tp-sr" for="tp-kind">Area type</label>
          <select id="tp-kind">
            <option value="county">Hennepin County</option>
            <option value="city">City</option>
            <option value="watershed">Watershed District</option>
            <option value="zoomto" hidden>Zoom to selection</option>
          </select>
          <label class="tp-sr" for="tp-area">Area</label>
          <select id="tp-area" hidden></select>
        </div>
        <div class="tp-scope" aria-live="polite"></div>
        <div class="tp-wrap">
          <table>
            <thead><tr>
              <th scope="col" class="tp-num">#</th><th scope="col" class="tp-num">Rank</th>
              <th scope="col">Class</th><th scope="col">PID</th><th scope="col">Address</th>
              <th scope="col">City</th><th scope="col" class="tp-num">Acres</th>
              <th scope="col" class="tp-num">Overall Value</th><th scope="col"><span class="tp-sr">Zoom</span></th>
            </tr></thead>
            <tbody></tbody>
          </table>
        </div>
        <div class="tp-foot">
          <span class="tp-count"></span>
          <button type="button" class="tp-more">Show 50 more</button>
          <button type="button" class="tp-csv">Download CSV</button>
        </div>
        <div class="tp-status"></div>
      </div>`;
    document.body.appendChild(panel);
    kindSel = panel.querySelector("#tp-kind");
    areaSel = panel.querySelector("#tp-area");
    scopeNote = panel.querySelector(".tp-scope");
    tbody = panel.querySelector("tbody");
    moreBtn = panel.querySelector(".tp-more");
    countLine = panel.querySelector(".tp-count");
    statusLine = panel.querySelector(".tp-status");

    kindSel.addEventListener("change", () => {
      const k = kindSel.value;
      if (k === "county") { zt.select("county"); setScope({ kind: "county" }); return; }
      if (k === "zoomto") { setScope(scopeFromZoomTo()); return; }
      fillAreas(k, null);
      areaSel.focus();
    });
    areaSel.addEventListener("change", () => {
      const k = kindSel.value, name = areaSel.value;
      if (!name) return;
      zt.select(k, name);
      setScope({ kind: k, items: [{ kind: k, name }] });
    });
    moreBtn.addEventListener("click", () => { shown += PAGE; render(); });
    panel.querySelector(".tp-csv").addEventListener("click", csv);
    panel.querySelector(".tp-close").addEventListener("click", () => toggle(false));
    panel.querySelector(".tp-grip").addEventListener("click", () => panel.classList.toggle("tp-collapsed"));
    panel.addEventListener("keydown", e => { if (e.key === "Escape") toggle(false); });
  }

  async function load() {
    if (data) return data;
    if (!loading) {
      statusLine.textContent = "Loading...";
      loading = fetch("data/top-parcels.json").then(r => r.json());
    }
    data = await loading;
    return data;
  }

  async function toggle(open) {
    const show = open ?? panel.classList.contains("hidden");
    panel.classList.toggle("hidden", !show);
    btn.classList.toggle("active", show);
    btn.setAttribute("aria-expanded", show ? "true" : "false");
    if (!show) return;
    await load();
    turnModelOn();
    setScope(scopeFromZoomTo());
    kindSel.focus();
  }

  function init(v, m, afterBtn) {
    view = v; model = m;
    if (!model || !model.layer || !window.NRPCProtectedV1) return null;
    btn = document.createElement("button");
    btn.id = "top-parcels-toggle";
    btn.className = "panel-toggle";
    btn.textContent = "Top parcels";
    btn.setAttribute("aria-controls", "top-parcels-panel");
    btn.setAttribute("aria-expanded", "false");
    afterBtn.after(btn);
    buildPanel();
    btn.addEventListener("click", () => toggle());

    // Zoom to -> table (user ticks, Full County, Clear); the table's own drive is ignored
    document.addEventListener("change", e => {
      if (driving || !e.target.closest || !e.target.closest("#city-checkbox-scroll")) return;
      setScope(scopeFromZoomTo());
    });
    document.addEventListener("click", e => {
      if (driving || !e.target.closest || !e.target.closest("#city-clear-btn")) return;
      setScope({ kind: "county" });
    });
    view.watch(["popup.visible", "popup.selectedFeature"], onPopupChange);
    const api = { toggle, setScope, selectParcel, get rows() { return rows; },
                  get selectedPid() { return selectedPid; }, get scope() { return scope; } };
    if (window.__nrpc) window.__nrpc.top = api;     // ?debug only
    return api;
  }

  return { init };
})();
